```java
@Component
public class AssignmentSummaryEnricher {
    static final LookupKey<TaskEntity> TASK = LookupKey.of("task");
    static final LookupKey<TaskItemEntity> ITEM = LookupKey.of("item");
    static final LookupKey<String> LABELER = LookupKey.of("labelerName");

    private final BatchEnricher batchEnricher;
    private final ObjectMapper objectMapper;
    private final EnrichmentSpec<AssignmentEntity> spec;

    AssignmentSummaryEnricher(BatchEnricher batchEnricher,
                              TaskMapper taskMapper, TaskItemMapper itemMapper,
                              UserDisplayNameResolver resolver, ObjectMapper om) {
        this.batchEnricher = batchEnricher;
        this.objectMapper = om;
        this.spec = EnrichmentSpec.<AssignmentEntity>create()
            .lookup(TASK, AssignmentEntity::getTaskId,
                    MyBatisBatchLoaders.softDelete(taskMapper, TaskEntity::getId))
            .lookup(ITEM, AssignmentEntity::getItemId,
                    MyBatisBatchLoaders.softDelete(itemMapper, TaskItemEntity::getId))
            .lookup(LABELER, AssignmentEntity::getLabelerId,
                    UserDisplayLoader.displayNames(resolver));
    }

    public List<AssignmentSummary> enrichSummaries(List<AssignmentEntity> es) {
        return batchEnricher.enrich(es, spec, this::build);
    }
    public AssignmentSummary toSummary(AssignmentEntity e) {
        return batchEnricher.enrichOne(e, spec, this::build);
    }

    private AssignmentSummary build(AssignmentEntity e, EnrichmentContext ctx) {
        TaskEntity task = ctx.get(TASK, e.getTaskId());
        TaskItemEntity item = ctx.get(ITEM, e.getItemId());
        Map<String, Object> preview = item != null
                ? TaskPayloadPreviewSupport.toPayloadPreview(objectMapper, item.getPayloadJson())
                : Map.of();
        return new AssignmentSummary(
                e.getId(), e.getTaskId(), e.getItemId(), e.getSlotNo(),
                e.getLabelerId(), ctx.get(LABELER, e.getLabelerId()),
                e.getAssignType(), e.getStatus(),
                task != null ? task.getTitle() : null,
                task != null ? task.getTaskCode() : null,
                item != null ? item.getSeqNo() : null,
                item != null ? item.getSourceItemKey() : null,
                preview,
                e.getAssignedAt(), e.getClaimedAt(), e.getDeadlineAt(), e.getCreatedAt());
    }
}
```

`SubmissionSummaryEnricher` 同样：复用同一组 `LookupKey`（可下沉到一个共用 `TaskLookupKeys` 常量类，避免每个 Enricher 各自声明）。`toDetail` 多写一个 `buildDetail`，共享同一份 spec。

